  "enunciado": "Observe a frase atribuída a um economista fictício:\n\n\"Não foi o crédito que ficou mais caro. Foi a nossa memória dos juros baixos que ficou curta demais.\"\n\nDessa frase, deduz-se que, segundo o autor,",
