  "gabarito": "A",
  "comentario": "**Gabarito: A.**\n\n- **A (correta):** Os termos técnicos não são dominados pelo público: o código não é comum aos dois polos.\n- **B:** O emissor (o banco) está identificado.\n- **C:** O referente (segurança bancária) existe.\n- **D:** Não há impedimento de envio.\n- **E:** A mensagem chegou; o problema foi de compreensão.",
