  "enunciado": "\"O analista encarou a tela por um longo minuto. Mais um erro em produção! Quem teria aprovado aquele código sem testes? Respirou fundo e abriu o chamado.\"\n\nNo trecho, as frases \"Mais um erro em produção! Quem teria aprovado aquele código sem testes?\" exemplificam o discurso",
