  "gabarito": "E",
  "comentario": "**Gabarito: E.**\n\n- **A:** \"Mesmo que\" é concessivo.\n- **B:** \"Contanto que\" é condicional.\n- **C:** \"Conquanto\" é concessivo: o sentido passa a ser de oposição.\n- **D:** \"À medida que\" é proporcional.\n- **E (correta):** \"Como\" anteposto à principal tem valor causal, assim como \"visto que\".",
