  "enunciado": "Uma pessoa física passa a captar dinheiro do público prometendo rendimentos elevados e a \"aplicar\" os recursos, sem qualquer autorização do Banco Central. Pela Lei 7.492/1986, essa conduta pode configurar o crime de",
